#!/usr/bin/env bash
# Regenerate deps/vhir.lock: the version and hash of every third-party package
# that setup-sift.sh, quickstart-lite.sh and `vhir update` install.
#
#   deps/regen-lock.sh [--sift REV] [--vhir REV] [--opensearch REV] [--exclude-newer DATE]
#   deps/regen-lock.sh --check
#
# The lock is compiled from the three repos exported at the named commits
# (default HEAD), from packages published before DATE (default: 7 days ago).
# The same commits, DATE and uv version give the same file, byte for byte;
# the header records them and the command that reproduces it.
#
# --check compiles the current commits against the lock and fails if any
# package they need is missing from it or pinned differently: a dependency
# change that needs the lock regenerated. Run it before pushing any of the
# three repos.
#
# The other repos are found beside this one, as the installer lays them out
# (~/.vhir/src/{sift-mcp,vhir,opensearch-mcp}); VHIR_REPO and OPENSEARCH_REPO
# override that.
set -euo pipefail

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
SIFT_REPO=$(dirname "$HERE")
VHIR_REPO=${VHIR_REPO:-$SIFT_REPO/../vhir}
OPENSEARCH_REPO=${OPENSEARCH_REPO:-$SIFT_REPO/../opensearch-mcp}
LOCK="$HERE/vhir.lock"

SIFT_REV=HEAD VHIR_REV=HEAD OPENSEARCH_REV=HEAD
EXCLUDE_NEWER=$(date -u -d '7 days ago' +%Y-%m-%d)
CHECK=false
while [ $# -gt 0 ]; do
    case "$1" in
        --sift) SIFT_REV=$2; shift 2 ;;
        --vhir) VHIR_REV=$2; shift 2 ;;
        --opensearch) OPENSEARCH_REV=$2; shift 2 ;;
        --exclude-newer) EXCLUDE_NEWER=$2; shift 2 ;;
        --check) CHECK=true; shift ;;
        *) echo "unknown argument: $1" >&2; exit 2 ;;
    esac
done

# The first-party packages: installed editable, so never pinned in the lock.
# OpenCTI isn't locked: pycti's own pins can't resolve against the rest, so
# it installs separately, unlocked, after everything else.
SIFT_PACKAGES=(forensic-knowledge sift-common forensic-mcp sift-mcp sift-gateway
    case-mcp report-mcp case-dashboard windows-triage forensic-rag)
FIRST_PARTY=(forensic-knowledge sift-common forensic-mcp sift-mcp sift-gateway
    case-mcp report-mcp case-dashboard windows-triage-mcp rag-mcp vhir-cli
    opensearch-mcp opencti-mcp)
# pycti 6 and 7 both need otel 1.35.x; with these held the OpenCTI step
# leaves the locked packages in place (and chromadb importable).
HOLDS=("opentelemetry-sdk<1.36" "opentelemetry-api<1.36")

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT
mkdir -p "$WORK/src"/{sift-mcp,vhir,opensearch-mcp}

export_repo() {  # export_repo <repo> <rev> <dest>; prints the full commit
    local sha
    sha=$(git -C "$1" rev-parse --verify "$2^{commit}")
    git -C "$1" archive "$sha" | tar -x -C "$3"
    echo "$sha"
}
SIFT_SHA=$(export_repo "$SIFT_REPO" "$SIFT_REV" "$WORK/src/sift-mcp")
VHIR_SHA=$(export_repo "$VHIR_REPO" "$VHIR_REV" "$WORK/src/vhir")
OPENSEARCH_SHA=$(export_repo "$OPENSEARCH_REPO" "$OPENSEARCH_REV" "$WORK/src/opensearch-mcp")

{
    for p in "${SIFT_PACKAGES[@]}"; do echo "-e ./src/sift-mcp/packages/$p"; done
    echo "-e ./src/vhir"
    echo "-e ./src/opensearch-mcp"
} > "$WORK/lock.in"
printf '%s\n' "${HOLDS[@]}" > "$WORK/holds.txt"

NO_EMIT=()
for p in "${FIRST_PARTY[@]}"; do NO_EMIT+=(--no-emit-package "$p"); done
compile() {  # paths in the output are relative to $WORK, so they don't vary
    (cd "$WORK" && uv pip compile lock.in -c holds.txt "$@" \
        --universal --python-version 3.10 --no-header "${NO_EMIT[@]}" --quiet)
}

if $CHECK; then
    [ -f "$LOCK" ] || { echo "No lock at $LOCK" >&2; exit 1; }
    LOCK_DATE=$(sed -n 's/^# exclude-newer *\([^ ]*\).*/\1/p' "$LOCK")
    if ! compile -c "$LOCK" --exclude-newer "$LOCK_DATE" --no-annotate -o needed.txt 2> "$WORK/err"; then
        cat "$WORK/err" >&2
        echo "LOCK OUT OF DATE: the current dependencies can't be met from the lock. Run deps/regen-lock.sh" >&2
        exit 1
    fi
    pins() { grep -E '^[A-Za-z0-9._-]+==' "$1" | sed 's/ .*//' | tr 'A-Z_' 'a-z-' | sort -u; }
    missing=$(comm -23 <(pins "$WORK/needed.txt") <(pins "$LOCK"))
    if [ -n "$missing" ]; then
        echo "LOCK OUT OF DATE: needed but not in the lock:" >&2
        echo "$missing" | sed 's/^/  /' >&2
        echo "Run deps/regen-lock.sh" >&2
        exit 1
    fi
    echo "Lock OK: it covers every dependency of sift-mcp $SIFT_SHA, vhir $VHIR_SHA, opensearch-mcp $OPENSEARCH_SHA"
    exit 0
fi

compile --generate-hashes --exclude-newer "$EXCLUDE_NEWER" -o body.txt
{
    echo "# vhir dependency lock: generated by deps/regen-lock.sh; don't edit by hand."
    echo "# Installs and updates use it as a constraint (-c) and build constraint (-b)."
    echo "#"
    echo "# sift-mcp        $SIFT_SHA"
    echo "# vhir            $VHIR_SHA"
    echo "# opensearch-mcp  $OPENSEARCH_SHA"
    echo "# exclude-newer   $EXCLUDE_NEWER  (packages published before this date)"
    echo "# uv              $(uv --version | awk '{print $2}')"
    echo "# held            ${HOLDS[*]}  (pycti 6 and 7 need otel 1.35.x)"
    echo "# reproduce       deps/regen-lock.sh --sift $SIFT_SHA --vhir $VHIR_SHA --opensearch $OPENSEARCH_SHA --exclude-newer $EXCLUDE_NEWER"
    echo "#"
    cat "$WORK/body.txt"
} > "$LOCK"
echo "Wrote $LOCK"
